SELECT id, user_id, title, message_count, last_message_at, status, create_time, update_time
FROM agent_session
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 1

SELECT id, user_id, title, message_count, last_message_at, status, create_time, update_time
FROM agent_session
WHERE user_id = #{userId}
  AND status = 1
ORDER BY COALESCE(last_message_at, create_time) DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE agent_session
SET status = 0,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 1
